/**
 * @module integrations
 * Integration metadata and SVG icons for all connectors.
 *
 * @example
 * ```ts
 * import {
 *   getConnector,
 *   getIcon,
 *   getRemoteIntegrationToolDiscovery,
 *   getRemoteIntegrationToolDefinitions,
 *   createSalesforceServiceAccountToolSource,
 *   listConnectors,
 * } from "veryfront/integrations";
 *
 * const connectors = listConnectors();
 * const slack = getConnector("slack");
 * const slackIcon = getIcon("slack"); // raw SVG string
 * const discovery = await getRemoteIntegrationToolDiscovery();
 * const runtimeTools = await getRemoteIntegrationToolDefinitions();
 * ```
 */
import "../../_dnt.polyfills.js";
export { EnvVarSchema, IntegrationConfigSchema, IntegrationEndpointHistoricalSummarySchema, IntegrationNameSchema, IntegrationPromptSchema, IntegrationToolSchema, OAuthConfigSchema, OAuthFieldSchema, } from "./schema.js";
import { connectors, icons } from "./_data.js";
import { filterCatalogVisibleIntegrations, isCatalogVisibleIntegration } from "./feature-flags.js";
const iconMap = new Map(Object.entries(icons));
/** Return connector. */
export function getConnector(name) {
    if (!isCatalogVisibleIntegration(name))
        return undefined;
    return connectors.find((connector) => connector.name === name);
}
/** List connectors. */
export function listConnectors() {
    return filterCatalogVisibleIntegrations(connectors);
}
/** Return connector names. */
export function getConnectorNames() {
    return listConnectors().map((connector) => connector.name);
}
/** Return icon. */
export function getIcon(name) {
    if (!isCatalogVisibleIntegration(name))
        return undefined;
    return iconMap.get(name);
}
// Remote integration tool helpers (per-request, no global registration)
export { executeRemoteIntegrationTool, getRemoteIntegrationToolDefinitions, getRemoteIntegrationToolDiscovery, isRemoteIntegrationTool, runRemoteIntegrationTool, } from "./remote-tools.js";
export { createLocalIntegrationToolSource } from "./local-tool-source.js";
export { createSalesforceServiceAccountToolSource, SALESFORCE_SERVICE_ACCOUNT_ENV_VARS, } from "./salesforce-service-account.js";
export { createOutlookServiceAccountToolSource, OUTLOOK_SERVICE_ACCOUNT_ENV_VARS, } from "./outlook-service-account.js";
export { createIntegrationClient, IntegrationApiError } from "./client.js";
export { createIntegrationErrorContext, isIntegrationErrorContext, readIntegrationErrorContext, readIntegrationThrowableContext, } from "./error-context.js";
export { MAX_REMOTE_INTEGRATION_TOOL_NAME_LENGTH } from "./limits.js";
export { parseIntegrationToolIdentity } from "./source-policy.js";
